const now = new Date();
const friday = new Date(now);
friday.setHours(0, 0, 0, 0);
friday.setDate(friday.getDate() - ((friday.getDay() + 6) % 7));
if (friday > now) friday.setDate(friday.getDate() - 7);

const monday = new Date(friday);
monday.setDate(monday.getDate() + 1);
monday.setHours(0, 0, 0, 0);

const weekStart = monday.toISOString().split('T')[0];
const weekEnd = friday.toISOString().split('T')[13:15] ? friday.toISOString().split('T')[0] : friday.toISOString().split('T')[0];

return {
  json: {
    weekStart: weekStart,
    weekEnd: weekEnd,
    repo: $('Weekly Cron').item.json.repo || 'owner/repo',
    language: $('Weekly Cron').item.json.language || 'en',
    discordWebhook: $('Weekly Cron').item.json.discordWebhook || '',
    slackWebhook: $('Weekly Cron').item.json.slackWebhook || ''
  }
};

const commits = items.find(i => i.node === 'Fetch Commits')?.json || [];
const issues = items.find(i => i.node === 'Fetch Closed Issues')?.json || [];
const prs = items.find(i => i.node === 'Fetch Merged PRs')?.json || [];

// Filter only merged PRs (has merged_at)
const mergedPRs = prs.filter(p => p.merged_at);

// Filter issues that are not PRs
const closedIssues = issues.filter(i => !i.pull_request);

// Summarize commits by author
const authorCounts = {};
commits.forEach(c => {
  const author = c.commit.author?.name || c.author?.login || 'Unknown';
  authorCounts[author] = (authorCounts[author] || 0) + 1;
});

// Top contributors
const topContributors = Object.entries(authorCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([name, count]) => `${name}: ${count} commit${count > 1 ? 's' : ''}`);

// Key changes
const keyPRs = mergedPRs.slice(0, 10).map(p => `PR #${p.number}: ${p.title} (${p.user?.login})`);
const keyIssues = closedIssues.slice(0, 10).map(i => `Issue #${i.number}: ${i.title} (${i.user?.login})`);

return {
  json: {
    weekStart: $('Calculate Week Dates').item.json.weekStart,
    weekEnd: $('Calculate Week Dates').item.json.weekEnd,
    repo: $('Calculate Week Dates').item.json.repo,
    language: $('Calculate Week Dates').item.json.language,
    totalCommits: commits.length,
    totalMergedPRs: mergedPRs.length,
    totalClosedIssues: closedIssues.length,
    topContributors: topContributors,
    keyPRs: keyPRs,
    keyIssues: keyIssues,
    allCommits: commits.slice(0, 20).map(c => ({
      sha: c.sha?.substring(0, 7),
      message: c.commit.message?.split('\n')[0],
      author: c.commit.author?.name || c.author?.login,
      date: c.commit.author?.date
    })),
    allPRs: mergedPRs.slice(0, 20).map(p => ({
      number: p.number,
      title: p.title,
      author: p.user?.login,
      mergedAt: p.merged_at
    })),
    allIssues: closedIssues.slice(0, 20).map(i => ({
      number: i.number,
      title: i.title,
      author: i.user?.login,
      closedAt: i.closed_at
    }))
  }
};

