const data = $('Aggregate Data').item.json;

return {
  json: {
    summary: summary,
    repo: data.repo,
    weekStart: data.weekStart,
    weekEnd: data.weekEnd,
    totalCommits: data.totalCommits,
    totalMergedPRs: data.totalMergedPRs,
    totalClosedIssues: data.totalClosedIssues
  }
};

